-- Apply before deploying v0.16. Keep column and index in separate ALTER statements.
-- Shared index-build lock prevents NULL virtual-key entries for concurrent inserts.
ALTER TABLE events ADD COLUMN target_fingerprint BINARY(32) GENERATED ALWAYS AS (UNHEX(SHA2(JSON_OBJECT('kind',CASE WHEN LOWER(TRIM(TRAILING '.' FROM (CASE WHEN subtype='dns' THEN TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.qname')),'')) WHEN subtype='ssl' THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') WHEN subtype IN ('webfilter','app-ctrl') THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') ELSE '' END)))<>'' THEN 'domain' WHEN subtype='dns' THEN 'dns_missing' WHEN COALESCE(INET6_NTOA(INET6_ATON(dstip)),TRIM(dstip))<>'' THEN 'ip' ELSE 'missing' END,'value',CASE WHEN LOWER(TRIM(TRAILING '.' FROM (CASE WHEN subtype='dns' THEN TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.qname')),'')) WHEN subtype='ssl' THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') WHEN subtype IN ('webfilter','app-ctrl') THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') ELSE '' END)))<>'' THEN LOWER(TRIM(TRAILING '.' FROM (CASE WHEN subtype='dns' THEN TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.qname')),'')) WHEN subtype='ssl' THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') WHEN subtype IN ('webfilter','app-ctrl') THEN COALESCE(NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.hostname')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.sni')),'')),''),NULLIF(TRIM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(fields,'$.servername')),'')),''),'') ELSE '' END))) WHEN subtype='dns' THEN '' ELSE COALESCE(INET6_NTOA(INET6_ATON(dstip)),TRIM(dstip)) END),256))) VIRTUAL, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE events ADD INDEX target_time(target_fingerprint,event_at), ALGORITHM=INPLACE, LOCK=SHARED;
